def two_pointers(arr, target):
    # assumes arr is already sorted; sorting here would invalidate
    # original indices and mutate the caller's list
    left, right = 0, len(arr) - 1
    while left < right:
        current = arr[left] + arr[right]
        if current == target:
            return [left, right]
        elif current < target:
            left += 1
        else:
            right -= 1
    return None
